CREATE FUNCTION public.enforce_membership_identity() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog AS $$
BEGIN
  IF NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.restaurant_id IS DISTINCT FROM OLD.restaurant_id THEN
    RAISE EXCEPTION 'Membership user and restaurant are immutable'
      USING ERRCODE = '23514', CONSTRAINT = 'merchant_memberships_identity_check';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER merchant_memberships_identity
  BEFORE UPDATE OF user_id, restaurant_id ON public.merchant_memberships
  FOR EACH ROW EXECUTE FUNCTION public.enforce_membership_identity();

-- Freeze location ownership so reassignment cannot invalidate selections/history.
