    RAISE EXCEPTION 'Location restaurant is immutable'
      USING ERRCODE = '23514', CONSTRAINT = 'restaurant_locations_restaurant_immutable_check';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER restaurant_locations_restaurant_immutable
