-- Serialize all association mutations through the owner, including direct SQL.
-- An actual UPDATE (not just a row lock) also prevents stale-snapshot write skew
-- under REPEATABLE READ: competing transactions must retry SQLSTATE 40001.
-- Callers modifying multiple memberships must lock owners in UUID order FIRST,
-- before touching association rows; row-trigger fallback may otherwise deadlock
-- (40P01, retry whole transaction), but cannot commit an invalid selection.
CREATE FUNCTION public.lock_membership_selection() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog AS $$
DECLARE
  owner_ids uuid[] := ARRAY[]::uuid[];
  owner_id uuid;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    owner_ids := array_append(owner_ids, OLD.membership_id);
  END IF;
  IF TG_OP <> 'DELETE' THEN
    owner_ids := array_append(owner_ids, NEW.membership_id);
  END IF;
  FOR owner_id IN SELECT DISTINCT id FROM unnest(owner_ids) AS owners(id) ORDER BY id LOOP
    UPDATE public.merchant_memberships SET updated_at = clock_timestamp() WHERE id = owner_id;
  END LOOP;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER merchant_membership_locations_lock
  BEFORE INSERT OR UPDATE OR DELETE ON public.merchant_membership_locations
  FOR EACH ROW EXECUTE FUNCTION public.lock_membership_selection();

-- Check final state, not transition rows captured earlier in the transaction.
-- Both ends and both OLD/NEW membership IDs are covered, including moves/deletes.
CREATE FUNCTION public.enforce_membership_scope() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog AS $$
DECLARE
  owner_ids uuid[] := ARRAY[]::uuid[];
  owner_id uuid;
  owner_restaurant uuid;
  owner_scope public.membership_scope_type;
  has_locations boolean;
BEGIN
  IF TG_TABLE_NAME = 'merchant_memberships' THEN
    IF TG_OP <> 'INSERT' THEN owner_ids := array_append(owner_ids, OLD.id); END IF;
    IF TG_OP <> 'DELETE' THEN owner_ids := array_append(owner_ids, NEW.id); END IF;
  ELSE
    IF TG_OP <> 'INSERT' THEN owner_ids := array_append(owner_ids, OLD.membership_id); END IF;
    IF TG_OP <> 'DELETE' THEN owner_ids := array_append(owner_ids, NEW.membership_id); END IF;
  END IF;

  FOR owner_id IN SELECT DISTINCT id FROM unnest(owner_ids) AS owners(id) ORDER BY id LOOP
    SELECT restaurant_id, scope_type INTO owner_restaurant, owner_scope
      FROM public.merchant_memberships WHERE id = owner_id;
    IF NOT FOUND THEN CONTINUE; END IF;

    SELECT EXISTS (SELECT 1 FROM public.merchant_membership_locations WHERE membership_id = owner_id)
      INTO has_locations;
    IF (owner_scope = 'ALL_LOCATIONS' AND has_locations)
       OR (owner_scope = 'SELECTED_LOCATIONS' AND NOT has_locations) THEN
      RAISE EXCEPTION 'Membership selection does not match scope_type'
        USING ERRCODE = '23514', CONSTRAINT = 'merchant_memberships_scope_check';
    END IF;

    IF EXISTS (
      SELECT 1 FROM public.merchant_membership_locations AS selection
      JOIN public.restaurant_locations AS location ON location.id = selection.location_id
      WHERE selection.membership_id = owner_id AND location.restaurant_id <> owner_restaurant
    ) THEN
      RAISE EXCEPTION 'Selected location belongs to another restaurant'
        USING ERRCODE = '23514', CONSTRAINT = 'merchant_membership_locations_restaurant_check';
    END IF;
  END LOOP;
  RETURN NULL;
END;
$$;

CREATE CONSTRAINT TRIGGER merchant_memberships_scope
  AFTER INSERT OR UPDATE OR DELETE ON public.merchant_memberships
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION public.enforce_membership_scope();

CREATE CONSTRAINT TRIGGER merchant_membership_locations_scope
  AFTER INSERT OR UPDATE OR DELETE ON public.merchant_membership_locations
